"summary": "Renderer's CPU limit is too low, causing throttling. Increase its limit to 1.5 cores despite log-shipper issues, as the logs indicate buffer fullness due to log-shipper's CPU starvation, not renderer's throttling.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Renderer is throttled at 1 CPU limit with 0.93 usage, and previous version also had throttling but possibly lower load.",
    "supporting": ["ev-container_cpu", "ev-revision_health"],
