    "status": "supported"
  },
  {
    "root_cause_class": "transient_cpu_burst",
    "summary": "Logs show renderer waiting on log-shipper due to buffer fullness, which may indicate log-shipper's CPU starvation rather than renderer's throttling.",
    "supporting": ["ev-container_logs_tail"],
    "contradicting": ["ev-target_events"],
    "missing": ["cpu_usage_comparison_between_revisions"],
    "status": "supported"
