],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "reports",
    "uid": "uid-deployment-reports"
  },
  "params": {
    "containers": {
      "renderer": {
        "limits": {
          "cpu": "1500m"
        }
      }
    }
  },
  "expected_effect": "Raise renderer's CPU limit to 1.5 cores to clear throttling, based on 1.5x current limit of 1 core.",
  "rationale": "Renderer is throttled at 1 CPU limit with 0.93 usage (41% throttling), and previous version also had throttling. Logs show renderer waiting on log-shipper due to buffer fullness, which may indicate log-shipper's CPU starvation. Increasing renderer's limit to 1.5 cores should alleviate the throttling without changing other containers or memory limits.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-revision_health", "ev-container_logs_tail"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "throttling_came_with_rollout"]
}
}
